var a=`0159-pizza-marinara`;var t=`world-0159`;var n=`IT`;var o=`southern-europe`;var r=4;var l=125;var s={en:`Pizza Marinara`,ua:`Піца Маринара`};var u={en:`A classic dish from Italy, featuring garlic, 00 flour, instant yeast, extra virgin olive oil. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: часник, пшеничне борошно типу 00, інстантні дріжджі, оливкова олія екстра вірджин. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 90 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 90 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:90,i:[[`00-flour`,530,`g`],[`water`,330,`ml`],[`instant-yeast`,3,`g`],[`table-salt`,11,`g`],[`extra-virgin-olive-oil`,20,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:20,i:[]},{en:`Cook the listed sauce ingredients over medium-low heat for about 5 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 5 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:5,i:[[`tomato-passata`,300,`g`],[`garlic`,4,`clove`],[`dried-oregano`,5,`g`]]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 10 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 10 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:10,i:[[`extra-virgin-olive-oil`,35,`ml`]]}];var d={slug:a,id:t,country:`IT`,region:o,servings:4,minutes:125,title:s,text:u,steps:g};export{n as country,d as default,t as id,l as minutes,o as region,r as servings,a as slug,g as steps,u as text,s as title};